// Widths generated by scripts/optimize-images.mjs; keep the two in sync.
const photoWidths: Record<string, number[]> = {
  skardu: [480, 768, 1280, 1920],
  hunza: [480, 720, 880],
  "fairy-meadows": [480, 800, 1200],
};

export const photo = (name: string) => {
  const widths = photoWidths[name];
  return {
    src: `/images/${name}-${widths[1]}.webp`,
    srcSet: widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(", "),
  };
};

const galleryImage = (name: string) => ({
  src: `/images/${name}-800.webp`,
  srcSet: `/images/${name}-400.webp 400w, /images/${name}-800.webp 800w`,
});

